if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'';if($action==='update_profile'){$name=trim($_POST['admin_name']??'');$email=trim($_POST['admin_email']??'');if($name===''||$email==='')$error='Please fill in all fields.';elseif(!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Please enter a valid email address.';else{$_SESSION['admin_name']=$name;$_SESSION['admin_email']=$email;$adminName=$name;$adminEmail=$email;$success='Profile updated successfully.';}}if($action==='change_password'){$current=$_POST['current_password']??'';$new=$_POST['new_password']??'';$confirm=$_POST['confirm_password']??'';$stored=$_SESSION['admin_password']??'admin123';if($current===''||$new===''||$confirm==='')$error='Please fill in all password fields.';elseif($current!==$stored)$error='Current password is incorrect.';elseif(strlen($new)<6)$error='New password must contain at least 6 characters.';elseif($new!==$confirm)$error='New password and confirm password do not match.';else{$_SESSION['admin_password']=$new;$success='Password changed successfully.';}}}
?>
